fn centre_x(l: &Led) -> f32 {
    (l.3[0] + l.3[2]) as f32 / 2.0
}

/// LED indices of `layout` ordered left to right (ties keep table order).
pub fn left_to_right(layout: &[Led]) -> Vec<u8> {
    let mut v: Vec<&Led> = layout.iter().collect();
    v.sort_by(|a, b| centre_x(a).total_cmp(&centre_x(b)));
    v.into_iter().map(|l| l.0).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn f99_has_99_unique_leds() {
        assert_eq!(F99.len(), 99);
        let mut idx: Vec<u8> = F99.iter().map(|l| l.0).collect();
        idx.sort();
        idx.dedup();
        assert_eq!(idx.len(), 99);
        assert!(idx.iter().all(|&i| i <= 112));
        assert!(F99.iter().all(|l| l.3[0] < l.3[2] && l.3[1] < l.3[3]));
    }

    #[test]
    fn order_starts_left_ends_right() {
        let o = left_to_right(F99);
        assert_eq!(o.len(), 99);
        assert_eq!(o[0], 0); // Esc
        assert_eq!(*o.last().unwrap(), 108); // Page Down, last listed of the right-most column
    }
}
